/**
 * The TypeScript SDK: a typed client over the API's OpenAPI document
 * (openapi-fetch + types generated by openapi-typescript).
 */
import { describe, expect, it, vi } from 'vitest';

import { createKpiNexusClient } from './index.js';

describe('createKpiNexusClient', () => {
  it('calls the API at baseUrl with the bearer token and fills path parameters', async () => {
    const fetchMock = vi.fn(async (_req: Request) => new Response(JSON.stringify([{ id: 'p1', value: 42 }]), { status: 200, headers: { 'content-type': 'application/json' } }));
    const api = createKpiNexusClient({ baseUrl: 'https://api.example.test', token: 'tok-123', fetch: fetchMock as unknown as typeof fetch });

    const { data, response } = await api.GET('/kpis/{id}/data', { params: { path: { id: 'k 1' } } });

    expect(response.status).toBe(200);
    expect(data).toEqual([{ id: 'p1', value: 42 }]);
    const req = fetchMock.mock.calls[0]![0];
    expect(req.url).toBe('https://api.example.test/kpis/k%201/data');
    expect(req.headers.get('authorization')).toBe('Bearer tok-123');
  });

  it('sends a typed JSON body', async () => {
    const fetchMock = vi.fn(async (_req: Request) => new Response('{}', { status: 201, headers: { 'content-type': 'application/json' } }));
    const api = createKpiNexusClient({ baseUrl: 'https://api.example.test', token: 't', fetch: fetchMock as unknown as typeof fetch });
    await api.POST('/kpis/{id}/data', {
      params: { path: { id: 'k1' } },
      body: { value: 5, periodStart: '2026-11-01T00:00:00.000Z', periodEnd: '2026-11-30T00:00:00.000Z' },
    });
    const req = fetchMock.mock.calls[0]![0];
    expect(req.method).toBe('POST');
    expect(await req.json()).toMatchObject({ value: 5 });
  });

  it('without a token, sends no authorization header (public endpoints)', async () => {
    const fetchMock = vi.fn(async (_req: Request) => new Response('{}', { status: 200, headers: { 'content-type': 'application/json' } }));
    const api = createKpiNexusClient({ baseUrl: 'https://api.example.test', fetch: fetchMock as unknown as typeof fetch });
    await api.GET('/health');
    expect(fetchMock.mock.calls[0]![0].headers.get('authorization')).toBeNull();
  });
});
